<?php
require __DIR__ . '/../app/bootstrap.php';
require_admin();
$db = database();
if ($_SERVER['REQUEST_METHOD'] === 'POST' && verify_csrf('activities', $_POST['csrf'] ?? null)) { try { activity_create($db, trim($_POST['admin_name'] ?? ''), trim($_POST['public_title'] ?? ''), trim($_POST['slug'] ?? ''), isset($_POST['duplicate']) ? (int) $_POST['duplicate'] : null); header('Location: /admin/activities.php', true, 303); exit; } catch (Throwable $e) { $error = $e->getMessage(); } }
$rows = $db->query('SELECT a.*, d.draft_revision, d.published_revision, (SELECT COUNT(*) FROM interest_submissions i WHERE i.activity_id = a.id) responses FROM activities a LEFT JOIN content_documents d ON d.activity_id = a.id ORDER BY a.is_root DESC, a.updated_at DESC')->fetchAll();
$activityLabel = count($rows) === 1 ? 'activity' : 'activities';
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/admin/admin.css"><title>Activities</title></head><body class="admin-page"><main class="admin-shell"><header class="admin-header"><div><p class="admin-kicker">Workshop administration</p><h1 class="admin-title">Activities</h1></div><nav class="admin-nav" aria-label="Administration"><a href="/admin/activities.php" aria-current="page">Activities</a><a href="/admin/interests.php">Responses</a></nav></header><div class="admin-grid"><section class="admin-panel"><h2>New activity</h2><?php if (isset($error)): ?><p class="admin-error" role="alert"><?= h($error) ?></p><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= h(csrf_token('activities')) ?>"><label class="admin-field">Name<input name="admin_name" required></label><label class="admin-field">Public title<input name="public_title" required></label><label class="admin-field">Slug<input name="slug" required></label><button class="admin-button">Create activity</button></form></section><section><div class="admin-toolbar"><div><p class="admin-kicker">Existing activities</p><h2 class="admin-list-title">All activities</h2></div><p class="admin-count"><?= count($rows) ?> <?= $activityLabel ?></p></div><div class="activity-list"><?php foreach ($rows as $r): $responseLabel = (int) $r['responses'] === 1 ? 'response' : 'responses'; ?><article class="activity-card"><h3><?= h($r['admin_name']) ?></h3><p class="admin-meta"><span class="meta-identity">Slug <b>/<?= h($r['slug']) ?></b></span><span class="meta-state">Status <b><?= h($r['status']) ?></b></span><span class="meta-revision">Draft <b><?= h($r['draft_revision']) ?></b></span><span class="meta-revision">Published <b><?= h($r['published_revision']) ?></b></span><span class="meta-responses">Responses <b><?= h($r['responses']) ?> <?= $responseLabel ?></b></span></p><nav class="admin-actions" aria-label="Actions for <?= h($r['admin_name']) ?>"><a href="/editor/?activity=<?= $r['id'] ?>">Edit</a><a href="/admin/preview.php?activity=<?= $r['id'] ?>">Preview</a><a href="/<?= h($r['slug']) ?>/">Public page</a></nav></article><?php endforeach; ?></div></section></div></main></body></html>
